use std::collections::HashMap;

/// Represents a recruitment email item.
#[derive(Debug, Clone)]
pub struct MailItem {
    pub subject: String,
}

/// Represents a stage in the recruitment funnel.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Stage {
    Resume,
    WrittenExam,
    Interview,
    Offer,
}

impl Stage {
    /// Returns all stages in funnel order.
    pub fn all() -> [Stage; 4] {
        [Stage::Resume, Stage::WrittenExam, Stage::Interview, Stage::Offer]
    }

    /// Returns a human-readable label for the stage.
    pub fn label(&self) -> &'static str {
        match self {
            Stage::Resume => "Resume",
            Stage::WrittenExam => "Written Exam",
            Stage::Interview => "Interview",
            Stage::Offer => "Offer",
        }
    }
}

/// Classifies an email subject into a funnel stage based on keyword matching.
/// Priority order (descending): Offer → Interview → Written Exam → Resume.
/// Returns `None` for empty or unrelated subjects.
fn classify_stage(subject: &str) -> Option<Stage> {
    let subject = subject.trim();
    if subject.is_empty() {
        return None;
    }

    let lower = subject.to_lowercase();

    // Priority order: Offer first (highest priority)
    if lower.contains("offer") {
        return Some(Stage::Offer);
    }

    // Interview
    if lower.contains("interview") {
        return Some(Stage::Interview);
    }

    // Written Exam
    if lower.contains("written exam") || lower.contains("written") {
        return Some(Stage::WrittenExam);
    }

    // Resume
    if lower.contains("resume") || lower.contains("cv") {
        return Some(Stage::Resume);
    }

    None
}

/// Analyzes a slice of mail items and returns counts per stage in funnel order.
pub fn analyze(items: &[MailItem]) -> Vec<(Stage, usize)> {
    let mut counts: HashMap<Stage, usize> = HashMap::new();

    for item in items {
        if let Some(stage) = classify_stage(&item.subject) {
            *counts.entry(stage).or_insert(0) += 1;
        }
    }

    Stage::all()
        .iter()
        .map(|stage| (*stage, counts.get(stage).copied().unwrap_or(0)))
        .collect()
}

/// Formats the funnel analysis as a Markdown table with conversion rates and ASCII bar visualization.
pub fn format_funnel(items: &[MailItem]) -> String {
    let results = analyze(items);
    let max_count = results.iter().map(|(_, count)| *count).max().unwrap_or(0);

    let mut output = String::new();
    output.push_str("| Stage | Count | Conversion | Bar |\n");
    output.push_str("|-------|-------|------------|-----|\n");

    for (i, (stage, count)) in results.iter().enumerate() {
        let label = stage.label();
        let conversion = if i == 0 {
            "—".to_string()
        } else {
            let prev_count = results[i - 1].1;
            if prev_count == 0 {
                "—".to_string()
            } else {
                let rate = (*count as f64 / prev_count as f64) * 100.0;
                format!("{:.1}%", rate)
            }
        };

        let bar_length = if max_count == 0 {
            0
        } else {
            (*count as f64 / max_count as f64 * 20.0).round() as usize
        };
        let bar = "█".repeat(bar_length);

        output.push_str(&format!("| {} | {} | {} | {} |\n", label, count, conversion, bar));
    }

    output
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_classify_stage() {
        assert_eq!(classify_stage("Offer Letter"), Some(Stage::Offer));
        assert_eq!(classify_stage("Interview Invitation"), Some(Stage::Interview));
        assert_eq!(classify_stage("Written Exam Schedule"), Some(Stage::WrittenExam));
        assert_eq!(classify_stage("Resume Received"), Some(Stage::Resume));
        assert_eq!(classify_stage("CV Submission"), Some(Stage::Resume));
        assert_eq!(classify_stage(""), None);
        assert_eq!(classify_stage("Meeting Reminder"), None);
    }

    #[test]
    fn test_priority_matching() {
        // Should match Offer (highest priority) even if multiple keywords present
        assert_eq!(
            classify_stage("Offer after Interview"),
            Some(Stage::Offer)
        );
        assert_eq!(
            classify_stage("Interview for Resume Review"),
            Some(Stage::Interview)
        );
    }

    #[test]
    fn test_analyze() {
        let items = vec![
            MailItem { subject: "Resume Submission".into() },
            MailItem { subject: "Written Exam Details".into() },
            MailItem { subject: "Interview Invitation".into() },
            MailItem { subject: "Offer Letter".into() },
            MailItem { subject: "Unrelated".into() },
        ];

        let result = analyze(&items);
        assert_eq!(result.len(), 4);
        assert_eq!(result[0], (Stage::Resume, 1));
        assert_eq!(result[1], (Stage::WrittenExam, 1));
        assert_eq!(result[2], (Stage::Interview, 1));
        assert_eq!(result[3], (Stage::Offer, 1));
    }

    #[test]
    fn test_format_funnel() {
        let items = vec![
            MailItem { subject: "Resume".into() },
            MailItem { subject: "Resume".into() },
            MailItem { subject: "Written Exam".into() },
            MailItem { subject: "Interview".into() },
            MailItem { subject: "Offer".into() },
        ];

        let output = format_funnel(&items);
        assert!(output.contains("| Stage | Count | Conversion | Bar |"));
        assert!(output.contains("| Resume | 2 | — |"));
        assert!(output.contains("| Written Exam | 1 | 50.0% |"));
        assert!(output.contains("| Interview | 1 | 100.0% |"));
        assert!(output.contains("| Offer | 1 | 100.0% |"));
    }
}

